  // ---------------------------------------------------------------- troubleshoot
  "trouble.list": ["Start here: pick the problem that looks most like what you see.", "Yes/no questions go cheapest first; the first No names the cause and the fix.", null],
  "trouble.sym.pod_wrong_direction": ["Checks offsets, encoder direction and steering ratio, then a steering test.", "Most often an offset copied from another robot or rounded off.", "offset"],
  "trouble.sym.wheel_backwards": ["Checks drive inversion in the files, then watches each tire on blocks.", "Usually a module captured 180° off and \"fixed\" by inverting its drive.", "bevel_gear"],
  "trouble.sym.robot_wrong_direction": ["Checks each module, then the stick signs and the gyro on the floor.", "An Xbox stick pushed forward reads -1, so a missing minus sign flips the robot.", "inversion"],
  "trouble.sym.field_relative_wrong": ["Checks gyro direction, where the heading was zeroed, drift, and the spin test.", "\"Forward\" is wherever the robot faced when the gyro was zeroed.", "field_relative"],
  "trouble.sym.pod_oscillates": ["Checks ramp rate, overshoot, drive gains, loose parts and sensor noise.", "Usually too much push for the braking (kP against kD), or slop in the module.", "oscillation"],
  "trouble.sym.pod_slow": ["Checks ramp rate, steering speed on carpet, and both turn directions.", "Carpet grips a turning wheel, so gains tuned in the air are often too soft.", "carpet_scrub"],
  "trouble.sym.pod_not_moving": ["Checks controller faults, the encoder, then power and the pinion.", "When one module is dead and the others work, it's that module's wiring or parts.", "can_bus"],
  "trouble.sym.wont_drive_straight": ["Checks heading control, offsets, small steering errors, and matching wheel speeds.", "One degree of offset drifts about 1.7 cm per meter.", "offset"],
  "trouble.sym.skew_when_rotating": ["Checks steering speed, then the skew-correction setting.", "Wheels re-aim constantly while spinning; any lag curves the path.", "dead_time"],
  "trouble.sym.robot_slow": ["Checks max speed in the code, kV, binding modules and the battery.", "A wrong gear ratio or wheel size makes the code aim for the wrong speed.", "gear_ratio"],
  "trouble.sym.wheel_slip": ["Checks the drive current limit against the measured slip current, then the tread.", "Past the slip current, extra current only spins the wheel.", "slip_current"],
  "trouble.sym.brownout": ["Checks the drive current limit, the battery and CAN faults.", "Four drive motors at a high limit can sag the battery below what the roboRIO needs.", "voltage_sag"],
  "trouble.sym.auto_inaccurate": ["Checks PathPlanner's settings, odometry direction, wheel size, feedforward and slip.", "PathPlanner keeps its own copy of the robot; a wrong copy plans every path wrong.", "pathplanner_model"],
  "trouble.sym.twitchy": ["Checks max speed, stick shaping and drive kP.", "A straight-line stick is coarse at low speed; squaring it helps fine moves.", "deadband"],
  "trouble.sym.pod_jitter": ["Checks stick drift, encoder noise and steering kD.", "A stick resting slightly off center keeps sending tiny commands.", "stick_drift"],
  "trouble.sym.gear_ratio": ["Checks the hand-check ratio, each module's distance, and a taped straight line.", "YAGSL uses one ratio for all four modules; a different pinion fights the others.", "gear_ratio"],
  "trouble.sym.motor_hot": ["Checks current limits, drag, stalls, then whether the motor is too small.", "Heat grows with current squared, so a high limit cooks a motor fast.", "heat_estimate"],
  "trouble.sym.motor_dead": ["Checks faults, current flow, a hand spin, and kV over time.", "Output with no current means a broken wire; a falling kV means heat-weakened magnets.", "kV"],
  "trouble.sym.pod_drifts": ["Checks the motor encoder against the absolute encoder, then the pinion.", "The loop trusts the motor encoder, which can slip away from the true angle.", "encoder_sync"],
  "trouble.back": ["Back to the full list of problems.", "Your answers on this one are cleared.", null],
  "trouble.where": ["Where the robot must be to answer this question.", "Checks with the robot disabled come first, because nothing can move.", "environment"],
