  // ---------------------------------------------------------------- tune
  "tune.loop.steer": ["Tests how fast and exactly each wheel turns to the angle it's told.", "The wheel jumps between angles and the tool times how it gets there.", "step_response"],
  "tune.loop.slip": ["Finds the motor current where the wheels start spinning on carpet.", "The drive current limit belongs just below it, so power becomes push, not wheelspin.", "slip_current"],
  "tune.loop.ff": ["Measures the volts each wheel needs to start, hold a speed, and speed up.", "Knowing the volts ahead of time means PID barely has to work.", "feedforward"],
  "tune.loop.drive": ["Tests how well each wheel holds the speed it's told.", "Run it after Feedforward: feedforward does most of the work, PID fixes what's left.", "feedback"],
  "tune.loop.spin": ["Spins the robot in place both ways and compares the gyro with the wheels.", "If they disagree, the gyro or the module positions in the code are wrong.", "gyro"],
  "tune.loop.straight": ["Drives a measured straight line with no steering help.", "Drift shows offsets, wheel sizes or gear ratios that don't match the real robot.", "offset"],
  "tune.target.robot": ["Runs the test on the connected robot or the simulator.", "Only numbers measured on the real robot belong in the files.", "environment"],
  "tune.target.practice": ["Runs the test on a computer model of one MAXSwerve module.", "Nothing moves, so it's a safe place to learn what each gain does. Spin and Straight line need a whole robot.", "swerve_module"],
  "tune.surface.floor": ["Makes the practice wheel act like it stands on carpet.", "Carpet grips the tread as it turns, so steering needs more push near the target.", "carpet_scrub"],
  "tune.surface.blocks": ["Makes the practice wheel act like it's lifted off the floor.", "Nothing grips the tread, so it turns easily: good for first tries, not final numbers.", "environment"],
  "tune.module": ["Picks which module to test: all of them, or one (FL front-left, FR front-right, BL back-left, BR back-right).", "Test one module when only that one acts up.", "swerve_module"],
  "tune.pattern": ["Picks how big the angle jumps are.", "Small jumps show friction stopping the wheel short; large jumps show the motor running flat out.", "step_response"],
  "tune.run": ["Starts the test with the numbers in the Gains box.", "Every run is saved, so you can compare it with the next one.", null],
  "tune.gains": ["The controller settings the next run will use.", "Change one number, run, compare: two changes at once can't be told apart.", "feedback"],
  "tune.gain.kP": ["kP, the spring: push for each unit of error.", "More pulls harder toward the target, until it overshoots.", "kP"],
  "tune.gain.kI": ["kI, the grudge: push from error added up over time.", "Usually 0 here; too much makes the wheel overshoot and swing.", "kI"],
  "tune.gain.kD": ["kD, the damper: push against how fast the error is changing.", "It brakes the wheel near the target so it doesn't overshoot.", "kD"],
  "tune.gain.iZone": ["IZone: kI only works when the error is smaller than this.", "It stops the I term piling up during big moves.", "iZone"],
  "tune.gain.ramp": ["How long the motor takes to go from zero to full output.", "A ramp slows every correction; 0 means no ramp.", "ramp_rate"],
  "tune.gain.velwindow": ["How long the controller counts encoder ticks to measure speed.", "Shorter is quicker but noisier; 0 keeps the controller's own setting.", "velocity_filter"],
  "tune.gain.veldepth": ["How many speed readings are averaged.", "More is smoother but later; 0 keeps the controller's own setting.", "velocity_filter"],
  "tune.gain.kS": ["kS: the volts it takes just to get the wheel moving.", "It covers friction, so the PID doesn't have to.", "kS"],
  "tune.gain.kV": ["kV: the volts for each m/s of steady speed.", "With kV right, the wheel cruises at the speed it's told before PID does anything.", "kV"],
  "tune.gain.kA": ["kA: the volts for each m/s² of speeding up.", "It gives the extra push needed while the wheel accelerates.", "kA"],
  "tune.gain.skew": ["Corrects the sideways curve when the robot turns while driving.", "Small numbers only; the Spin and Straight line tests show whether it helps.", "dead_time"],
  "tune.gain.sync": ["Whether the motor encoder is reset to the absolute encoder while a wheel is still.", "It fixes slow drift between the two; 1 is on.", "encoder_sync"],
  "tune.gain.syncdb": ["How far apart the two encoders may be before a reset.", "Too small resets on noise; too big lets the wheel drift.", "encoder_sync"],
  "tune.apply": ["Sends the typed (amber) numbers to the robot right now, or to the practice pod.", "It's temporary: a restart reloads the files.", "redeploy"],
  "tune.revert": ["Throws away the numbers you typed.", "The boxes go back to what is running now.", null],
  "tune.save": ["Shows the exact file change, then writes the gains the robot is running into the code.", "Files count once you redeploy and commit.", "redeploy"],
  "tune.history": ["Your past runs of this test, newest first; pick a time to open one.", "Compare runs to see whether your last change helped.", null],
  "tune.title": ["Which test this is, where it ran, and when.", "Every run is saved; reopen it any time from here or the Runs tab.", null],
  "tune.cmp": ["Draws your previous run of this test behind this one, dotted.", "Before and after on one graph shows what your change did.", "step_response"],
  "tune.export": ["Saves this run as a log AdvantageScope opens (and SysId, for a feedforward run).", "Study it in the team's usual tools.", null],
  "tune.next": ["The one change the advice suggests trying next.", "One change per run, so you can tell what it did.", null],
  "tune.do": ["Makes the change written next to it.", "On the practice pod it also runs again; on the robot it changes the live robot.", null],
  "tune.steps": ["Zooms the graphs to one jump of the target; Whole run zooms back out.", "\"+45°\" means the target jumped 45 degrees.", "step_response"],
  "tune.xmod": ["Picks which module the lower graph and the story describe.", "Each module has its own loop, so each can behave differently.", "swerve_module"],
  "tune.metrics": ["Every jump of the target, in numbers, for every module.", "The targets above are graded from the worst row here.", "step_response"],
  "tune.whatif": ["Predicts this same run with different gains, from a model fitted to it.", "A prediction is a guess: apply the gains and run to see what really happens.", "what_if"],
  "tune.wi-use": ["Copies the slider values into the Gains box.", "Then apply and run to check the prediction.", "what_if"],
  "tune.wi-reset": ["Moves the sliders back to what this run used.", "Start over from what really happened.", "what_if"],
  "tune.story": ["Each idea this run shows, from the step that shows it best.", "Tap a name for its lesson; pick a step to read it moment by moment.", "step_response"],

